/* Page-level gradient background with dark mode support.
   Used by workflow stage pages and standalone screens so the background
   adapts to dark mode instead of staying a hardcoded light gradient. */
.page-gradient-bg {
  background: linear-gradient(135deg, #F5F3FF 0%, #FFF9F5 100%);
}
.dark .page-gradient-bg {
  background: #1a1a2e !important;
}

/* Estimator tab: flat SignEstimate Pro styling — plain white panels with thin
   gray borders, no claymorphic shadows or pastel gradients. */
.clay-scope,
.clay-scope [class*="bg-gradient-to"] {
  background: #f9fafb !important;
  background-image: none !important;
}

.clay-scope .clay-card,
.clay-scope .clay-button {
  background: #ffffff !important;
  border: 1px solid #e5e7eb !important;
  border-radius: 6px !important;
  box-shadow: none !important;
}

.clay-scope .bg-white {
  background: #ffffff !important;
  border-radius: 6px;
  box-shadow: none;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* SIPs board focused-row zoom: centered scale + symmetric animated gaps. */
@keyframes sipsGapGrow {
  from { height: 0; opacity: 0; }
  to { height: 10px; opacity: 1; }
}
tr.sips-focus-gap > td {
  padding: 0;
  border: 0;
}
.sips-focus-gap-inner {
  height: 10px;
  animation: sipsGapGrow 150ms ease-out;
}
tr.sips-board-row {
  transform-origin: 50% 50%;
  transition: transform 170ms cubic-bezier(0.22, 1.1, 0.36, 1),
    box-shadow 170ms ease, background-color 120ms ease;
}
tr.sips-focus-row {
  position: relative;
  z-index: 5;
  background: linear-gradient(180deg, #f5f3ff 0%, #ede9fe 100%);
  box-shadow: 0 12px 32px -12px rgba(109, 40, 217, 0.55),
    0 0 0 2px rgba(139, 92, 246, 0.9);
}
tr.sips-focus-row > td {
  padding-top: 9px;
  padding-bottom: 9px;
  font-size: 15px;
  transition: padding-top 150ms ease, padding-bottom 150ms ease, font-size 150ms ease;
}
tr.sips-focus-row > td :where(*) {
  font-size: inherit;
}
.sips-focus-num {
  background: linear-gradient(135deg, #8b5cf6 0%, #6d28d9 100%);
  box-shadow: inset 0 0 0 1.5px rgba(255, 255, 255, 0.6);
}
@media (prefers-reduced-motion: reduce) {
  tr.sips-board-row { transition: none; }
  .sips-focus-gap-inner { animation: none; }
}

